q:
In the figure, $O$ is the center of sector $OAB$. If $AQ=5$, $BQ=6$, and $OQ=PQ$, find the radius of the sector.

Here $XY$ denotes the length of segment $XY$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
real cross2(pair u,pair v) {return u.x*v.y-u.y*v.x;}
pair meet(pair p,pair v,pair q,pair w) {return p+cross2(q-p,w)/cross2(v,w)*v;}
size(250);
pair O=(0,0),A=dir(120),B=(1,0),P=dir(66);
pair Q=meet(O,P,A,B-A);
draw(O--A);draw(O--B);draw(arc(O,1,0,120));draw(A--B);draw(O--P);
label("O",O,(-1,-1));label("A",A,(-1,0));label("B",B,(1,-1));label("P",P,(1,1));label("Q",Q,(1,1));
[/asy]
